        public void HashAttributeDiff_Deterministic()
        {
            var d = new AttributeDiff();
            d.Key = "k1";
            d.Value = "v1";
            var h1 = Hashing.HashAttributeDiff(d);
            var h2 = Hashing.HashAttributeDiff(d);
            Assert.Equal(h1, h2);
            Assert.Equal(64, h1.Length);
        }

