        public void HashKitDiff_FieldOrderMatters()
        {
            var d1 = new KitDiff();
            d1.Name = "a";
            d1.Description = "b";
            var d2 = new KitDiff();
            d2.Name = "b";
            d2.Description = "a";
            Assert.NotEqual(Hashing.HashKitDiff(d1), Hashing.HashKitDiff(d2));
        }
    }

